import React from 'react';
import { FaFish, FaWater, FaTemperatureHigh, FaLeaf, FaInfo, FaStar, FaEdit, FaTrashAlt, FaFlask, FaTint, FaThermometerHalf } from 'react-icons/fa';

function AquariumList({ aquariums }) {
    if (!aquariums || aquariums.length === 0) {
        return <p style={{color:'#888', marginTop:'24px', animation: 'fadeIn 0.5s ease-out'}}>No aquariums yet. Add one!</p>;
    }

    return (
        <div style={{animation: 'fadeIn 0.6s ease-out'}}>
            <h3 style={{color:'#2563eb', marginBottom:'18px', animation: 'fadeIn 0.7s ease-out'}}>My Aquariums</h3>
            {aquariums.map((aq, index) => (
                <div 
                    key={aq.id} 
                    className={`card-aquarium ${aq.isNew ? 'new-item' : ''}`}
                    style={{
                        animationDelay: `${0.2 + index * 0.15}s`,
                        opacity: 0,
                        animation: `${aq.isNew ? 'highlight 2s ease-out, ' : ''}slideInFromRight 0.5s ease-out forwards`,
                        transform: aq.isNew ? 'scale(1.02)' : 'scale(1)',
                        transition: 'transform 0.5s ease-out'
                    }}
                >
                    {aq.photoUrl ? (
                        <img 
                            src={aq.photoUrl} 
                            alt={aq.name} 
                            onError={e => {
                                e.target.style.display='none';
                                e.target.parentNode.querySelector('.default-aquarium-icon').style.display = 'flex';
                            }} 
                            style={{
                                transition: 'transform 0.3s ease',
                                animation: 'scaleIn 0.5s ease-out',
                                border: aq.isNew ? '2px solid var(--color-primary-light)' : 'none',
                                boxShadow: aq.isNew ? '0 0 15px var(--color-primary-light)' : 'none'
                            }}
                            onMouseOver={e => e.target.style.transform = 'scale(1.1)'}
                            onMouseOut={e => e.target.style.transform = 'scale(1)'}
                        />
                    ) : (
                        <div 
                            className="default-aquarium-icon"
                            style={{
                                display: 'flex',
                                justifyContent: 'center',
                                alignItems: 'center',
                                backgroundColor: 'rgba(37, 99, 235, 0.1)',
                                borderRadius: '8px',
                                width: '100%',
                                height: '120px',
                                fontSize: '2.5rem',
                                color: 'var(--color-primary)',
                                transition: 'transform 0.3s ease',
                                animation: 'scaleIn 0.5s ease-out',
                                border: aq.isNew ? '2px solid var(--color-primary-light)' : 'none',
                                boxShadow: aq.isNew ? '0 0 15px var(--color-primary-light)' : 'none'
                            }}
                            onMouseOver={e => e.target.style.transform = 'scale(1.02)'}
                            onMouseOut={e => e.target.style.transform = 'scale(1)'}
                        >
                            <FaFish />
                        </div>
                    )}
                    <div className="card-aquarium-details" style={{textAlign:'left', width:'100%'}}>
                        <h4 style={{
                            animation: 'fadeIn 0.6s ease-out',
                            color: aq.isNew ? 'var(--color-primary)' : 'var(--color-text)'
                        }}>
                            {aq.name}
                            {aq.isNew && <span style={{
                                marginLeft: '8px',
                                fontSize: '0.7em',
                                backgroundColor: 'var(--color-primary-light)',
                                color: 'white',
                                padding: '2px 6px',
                                borderRadius: '10px',
                                animation: 'pulse 1.5s infinite'
                            }}>Nuevo</span>}
                        </h4>
                        <p style={{animation: 'fadeIn 0.7s ease-out', display: 'flex', alignItems: 'center', gap: '8px'}}>
                            <FaWater style={{color: 'var(--color-primary)'}} /> <strong>Volumen:</strong> {aq.volume} L
                        </p>
                        <p style={{animation: 'fadeIn 0.8s ease-out', display: 'flex', alignItems: 'center', gap: '8px'}}>
                            {getAquariumTypeIcon(aq.type)} <strong>Tipo:</strong> {getAquariumTypeLabel(aq.type)}
                        </p>
                        {aq.targetParameters && (
                            <p style={{animation: 'fadeIn 0.9s ease-out', display: 'flex', alignItems: 'center', gap: '8px'}}>
                                <FaFlask style={{color: 'var(--color-primary)'}} /> <strong>Parámetros:</strong> {aq.targetParameters}
                            </p>
                        )}
                        {aq.initialSetupNotes && (
                            <p style={{animation: 'fadeIn 1s ease-out', display: 'flex', alignItems: 'center', gap: '8px'}}>
                                <FaInfo style={{color: 'var(--color-primary)'}} /> <strong>Notas:</strong> {aq.initialSetupNotes}
                            </p>
                        )}
                        <div style={{display: 'flex', gap: '8px', marginTop: '12px'}}>
                            <button 
                                style={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: '4px',
                                    padding: '4px 8px',
                                    fontSize: '0.8rem',
                                    backgroundColor: 'var(--color-primary-light)',
                                    color: 'white',
                                    border: 'none',
                                    borderRadius: '4px',
                                    cursor: 'pointer'
                                }}
                            >
                                <FaEdit /> Editar
                            </button>
                            <button 
                                style={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: '4px',
                                    padding: '4px 8px',
                                    fontSize: '0.8rem',
                                    backgroundColor: 'rgba(220, 38, 38, 0.8)',
                                    color: 'white',
                                    border: 'none',
                                    borderRadius: '4px',
                                    cursor: 'pointer'
                                }}
                            >
                                <FaTrashAlt /> Eliminar
                            </button>
                        </div>
                    </div>
                </div>
            ))}
        </div>
    );
}

// Función para obtener el icono según el tipo de acuario
const getAquariumTypeIcon = (type) => {
    switch(type) {
        case 'Planted':
            return <FaLeaf style={{color: '#059669'}} />;
        case 'Community':
            return <FaFish style={{color: '#3B82F6'}} />;
        case 'Marine':
            return <FaTint style={{color: '#0284C7'}} />;
        case 'Reef':
            return <FaWater style={{color: '#F97316'}} />;
        case 'Brackish':
            return <FaWater style={{color: '#65A30D'}} />;
        case 'Coldwater':
            return <FaThermometerHalf style={{color: '#2563EB'}} />;
        case 'Species-specific':
            return <FaStar style={{color: '#8B5CF6'}} />;
        default:
            return <FaWater style={{color: '#6B7280'}} />;
    }
};

// Función para obtener la etiqueta en español según el tipo de acuario
const getAquariumTypeLabel = (type) => {
    switch(type) {
        case 'Planted':
            return 'Plantado';
        case 'Community':
            return 'Comunitario';
        case 'Marine':
            return 'Marino';
        case 'Reef':
            return 'Arrecife';
        case 'Brackish':
            return 'Agua salobre';
        case 'Coldwater':
            return 'Agua fría';
        case 'Species-specific':
            return 'Específico';
        default:
            return type;
    }
};

export default AquariumList;
